 85→// CalculateTokenUsage computes token usage from the transcript starting at the given message offset.
 86→func (g *GeminiCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
 87→	var transcript struct {
 88→		Messages []geminiMessageWithTokens `json:"messages"`
 89→	}
 90→
 91→	if err := json.Unmarshal(transcriptData, &transcript); err != nil {
 92→		return &agent.TokenUsage{}, fmt.Errorf("failed to parse transcript for token usage: %w", err)
 93→	}
 94→
 95→	usage := &agent.TokenUsage{}
 96→
 97→	for i, msg := range transcript.Messages {
 98→		// Skip messages before startMessageIndex
 99→		if i < fromOffset {
100→			continue
101→		}
102→
103→		// Only count tokens from gemini (assistant) messages
104→		if msg.Type != MessageTypeGemini {
105→			continue
106→		}
107→
108→		if msg.Tokens == nil {
109→			continue
110→		}
111→
112→		usage.APICallCount++
113→		usage.InputTokens += msg.Tokens.Input
114→		usage.OutputTokens += msg.Tokens.Output
115→		usage.CacheReadTokens += msg.Tokens.Cached
116→	}
117→
118→	return usage, nil
119→}
